const Finale: React.FC = () => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const pop = spring({ frame: f, fps, config: { damping: 14, stiffness: 110 } });
  const ring = tw(f, [0, 50], [0, 1]);
  const end = tw(f, [205, 240], [0, 1], Easing.inOut(Easing.cubic));
  const btn = spring({ frame: f - 95, fps, config: { damping: 16, stiffness: 120 } });
  return (
    <AbsoluteFill style={{ opacity: 1 - end }}>
      <Glow color={C.mint} y={470} opacity={0.2 + pop * 0.08} size={1600} />
      <div
        style={{
          position: "absolute",
          left: 960 - 400 * ring,
          top: 330 - 400 * ring,
          width: 800 * ring,
          height: 800 * ring,
          borderRadius: "50%",
          border: `3px solid ${C.mint}`,
          opacity: (1 - ring) * 0.8,
        }}
      />
      <Center top={200}>
        <div style={{ display: "flex", justifyContent: "center", scale: String(0.6 + pop * 0.4) }}>
          <Logo size={200} draw={1} glow={pop} />
        </div>
        <div style={{ height: 40 }} />
        <Line words={["Console", "Mode"]} at={6} size={170} weight={800} stagger={5} />
        <div style={{ height: 22 }} />
        <Line words={["Your", "PC.", { t: "Now", grad: true }, { t: "a", grad: true }, { t: "console.", grad: true }]} at={40} size={62} weight={600} stagger={4} color={C.muted} />
      </Center>
      <div style={{ position: "absolute", top: 830, left: 0, right: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 26 }}>
        <div
          style={{
            padding: "20px 50px",
            borderRadius: 999,
            background: C.text,
            color: "#000",
            fontFamily: SANS,
            fontSize: 34,
            fontWeight: 700,
            letterSpacing: "-0.01em",
            opacity: btn,
            scale: String(0.85 + btn * 0.15),
          }}
        >
          Download for Windows
        </div>
        <div style={{ fontFamily: SANS, fontSize: 30, fontWeight: 500, color: C.muted, opacity: tw(f, [110, 125], [0, 1], Easing.linear) }}>github.com/lippdev/consolemode</div>
      </div>
    </AbsoluteFill>
  );
};

