export const Keynote: React.FC = () => {
  const [handle] = useState(() => delayRender("Loading fonts"));
  useEffect(() => {
    Promise.all([
      document.fonts.load(`800 100px 'Inter Variable'`),
      document.fonts.load(`500 40px 'JetBrains Mono Variable'`),
    ]).then(
      () => continueRender(handle),
      () => continueRender(handle),
    );
  }, [handle]);

  return (
    <AbsoluteFill style={{ background: C.bg, overflow: "hidden" }}>
      <Audio src={staticFile("keynote/soundtrack.mp3")} />
      <Scene {...S.open}>
        <ColdOpen />
      </Scene>
      <Scene {...S.title}>
        <Title />
      </Scene>
      <Scene {...S.click}>
        <OneClick />
      </Scene>
      <Scene {...S.restore}>
        <Restore />
      </Scene>
      <Scene {...S.launchers}>
        <Launchers />
      </Scene>
      <Scene {...S.home}>
        <HoldHome />
      </Scene>
      <Scene {...S.menu}>
        <SessionMenu />
      </Scene>
      <Scene {...S.bento}>
        <Bento />
      </Scene>
      <Scene {...S.automate}>
        <Automate />
      </Scene>
      <Scene {...S.interfaces}>
        <Interfaces />
      </Scene>
      <Scene {...S.trust}>
        <Trust />
      </Scene>
      <Sequence from={S.finale.from} durationInFrames={S.finale.dur}>
        <Finale />
      </Sequence>
    </AbsoluteFill>
  );
};
